#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, c;
    cin >> a >> b >> c;

    __int128 sum = (__int128)a + b + c;
    __int128 ans = min(sum / 3, sum - max({a, b, c}));

    if (ans == 0) {
        cout << 0;
        return 0;
    }

    string result;
    while (ans > 0) {
        result.push_back(char('0' + ans % 10));
        ans /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;

    return 0;
}

